import ezdxf, sys

doc = ezdxf.readfile(sys.argv[1])
print("units", doc.units, "version", doc.dxfversion)
for e in doc.modelspace():
    d = e.dxf
    t = e.dxftype()
    if t == 'LINE':
        print(t, d.handle, d.layer, d.start, d.end)
    elif t == 'CIRCLE':
        print(t, d.handle, d.layer, d.center, d.radius)
    elif t == 'ARC':
        print(t, d.handle, d.layer, d.center, d.radius, d.start_angle, d.end_angle)
    elif t == 'LWPOLYLINE':
        print(t, d.handle, d.layer, list(e.get_points()), e.closed)
    elif t == 'TEXT':
        print(t, d.handle, d.layer, d.insert, repr(d.text))
    elif t == 'MTEXT':
        print(t, d.handle, d.layer, d.insert, repr(e.text))
    elif t == 'DIMENSION':
        print(t, d.handle, d.layer, 'type', d.dimtype, 'def', d.defpoint, 'p2', d.get('defpoint2'),
              'p3', d.get('defpoint3'), 'tm', d.get('text_midpoint'), 'text', repr(d.get('text')),
              'meas', e.get_measurement(), 'ang', d.get('angle'), 'blk', d.get('geometry'), 'style', d.get('dimstyle'))
    elif t == 'INSERT':
        print(t, d.handle, d.layer, d.name, d.insert, [(a.dxf.tag, a.dxf.text) for a in e.attribs])
    else:
        print(t, d.handle, d.layer)

