import ezdxf, sys

a = ezdxf.readfile(sys.argv[1])
b = ezdxf.readfile(sys.argv[2])


def snap(doc):
    out = {}
    for e in doc.modelspace():
        attrs = e.dxfattribs()
        attrs.pop('geometry', None)
        extra = None
        if e.dxftype() == 'LWPOLYLINE':
            extra = [tuple(round(v, 6) for v in p) for p in e.get_points('xyseb')]
        elif e.dxftype() == 'MTEXT':
            extra = e.text
        elif e.dxftype() == 'INSERT':
            extra = [(x.dxf.tag, x.dxf.text, x.dxf.insert) for x in e.attribs]
        elif e.dxftype() == 'HATCH':
            extra = [str(p.__dict__) for p in e.paths]
        out[e.dxf.handle] = (e.dxftype(), attrs, extra)
    return out


sa, sb = snap(a), snap(b)
print('same handle set:', set(sa) == set(sb))
for h in sa:
    if sa[h] != sb[h]:
        print('CHANGED', h, sa[h][0])
print('blocks a:', sorted(bl.name for bl in a.blocks))
print('blocks b:', sorted(bl.name for bl in b.blocks))
for name in ('*D6', '*D7'):
    for e in b.blocks.get(name):
        if e.dxftype() == 'MTEXT':
            print(name, 'MTEXT', repr(e.text))
for name in ('*D1', '*D5'):
    if name in a.blocks:
        for e in a.blocks.get(name):
            if e.dxftype() == 'MTEXT':
                print('orig', name, 'MTEXT', repr(e.text), 'color', e.dxf.get('color'))

msp = b.modelspace()
o = b.entitydb['91']
xs = [p[0] for p in o.get_points('xy')]
print('outline x range', min(xs), max(xs))
for c in msp.query('CIRCLE'):
    cx, cy = c.dxf.center.x, c.dxf.center.y
    print('hole', (cx, cy), 'r', c.dxf.radius, 'dist right', max(xs) - cx, 'dist left', cx - min(xs))
print('width dim measurement', b.entitydb['96'].get_measurement())

